99	// EmailConfigFromInstanceSetting converts persisted notification settings into SMTP config.
100	func EmailConfigFromInstanceSetting(setting *storepb.InstanceNotificationSetting_EmailSetting) *email.Config {
101		if setting == nil {
102			return &email.Config{}
103		}
104		return &email.Config{
105			SMTPHost:     setting.SmtpHost,
106			SMTPPort:     int(setting.SmtpPort),
107			SMTPUsername: setting.SmtpUsername,
108			SMTPPassword: setting.SmtpPassword,
109			FromEmail:    setting.FromEmail,
110			FromName:     setting.FromName,
111			UseTLS:       setting.UseTls,
112			UseSSL:       setting.UseSsl,
113		}
114	}
