256	func (s *APIV1Service) TestInstanceEmailSetting(ctx context.Context, request *v1pb.TestInstanceEmailSettingRequest) (*emptypb.Empty, error) {
257		user, err := s.fetchCurrentUser(ctx)
258		if err != nil {
259			return nil, status.Errorf(codes.Internal, "failed to get current user: %v", err)
260		}
261		if user == nil {
262			return nil, status.Errorf(codes.Unauthenticated, "user not authenticated")
263		}
264		if user.Role != store.RoleAdmin {
265			return nil, status.Errorf(codes.PermissionDenied, "permission denied")
266		}
267	
268		emailSetting, err := s.resolveTestEmailSetting(ctx, request.Email)
269		if err != nil {
270			return nil, err
271		}
272	
273		recipientEmail := strings.TrimSpace(request.RecipientEmail)
274		if recipientEmail == "" {
275			recipientEmail = strings.TrimSpace(user.Email)
276		}
277		if recipientEmail == "" {
278			return nil, status.Errorf(codes.InvalidArgument, "recipient email is required")
279		}
280	
281		if err := notification.ValidateEmailSetting(emailSetting); err != nil {
282			return nil, status.Errorf(codes.InvalidArgument, "invalid notification email setting: %v", err)
283		}
284	
285		if err := notification.SendTestEmail(emailSetting, recipientEmail); err != nil {
286			return nil, status.Errorf(codes.Internal, "failed to send test email: %v. Check that the SMTP port matches encryption: Gmail uses port 587 with STARTTLS on and SSL/TLS off; port 465 requires SSL/TLS on", err)
287		}
288	
289		return &emptypb.Empty{}, nil
290	}
